<template>


          <div class="container">
        <Mjuni/> 
    </div>

  <div class="layout-px-spacing">


<div class="d-flex ms-auto w-25">
    <Multiselect
      v-model="form"
      :options="forms"
      label="name"
      placeholder="Select form"
      :searchable="true"
    />
</div>


    <template v-if="form?.name">

      <!-- <DynamicForm :key="form.name" :form="form.name" @saved="tableRef.load()" /> -->

      <hr>

      <!-- <DynamicTable :key="form.name + '_table'" :form="form.name" ref="tableRef" /> -->
      <DynamicFormAndTable :key="form.name + '_table'" :form="form.name" ref="tableRef" />
    </template>

  </div>
</template>

<script setup>
import { ref, onMounted, watch, nextTick } from 'vue'
import axios from 'axios'
import DynamicForm  from '@/components/dynamicSchema/dynamicForm.vue'
import DynamicTable from '@/components/dynamicSchema/dynamicTable.vue'
import DynamicFormAndTable from '@/components/dynamicSchema/dynamicFormAndTable.vue'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'
import Mjuni from '@/components/dynamicSchema/navbar.vue'

const api = axios.create({ baseURL: 'https://bushman.ink/api/v2/' })

const tableRef = ref(null)
const forms    = ref([])
const form     = ref(null)

const getForms = async () => {
  const response = await api.get('form-lists')
  forms.value = response.data
}

watch(form, async () => {
  await nextTick()
  tableRef.value?.load()
})

onMounted(getForms)
</script>